def is_multiply_prime(a):
    """Write a function that returns true if the given number is the multiplication of 3 prime numbers
    and false otherwise.
    Knowing that (a) is less then 100. 
    Example:
    is_multiply_prime(30) == True
    30 = 2 * 3 * 5
    """

    def is_prime(n):
        if n < 2:
            return False
        if n == 2:
            return True
        if n % 2 == 0:
            return False
        for i in range(3, int(n ** 0.5) + 1, 2):
            if n % i == 0:
                return False
        return True

    if a < 2:
        return False

    # Try all combinations of 3 primes whose product equals a
    for i in range(2, a + 1):
        if not is_prime(i):
            continue
        if a % i != 0:
            continue
        remaining = a // i
        # Now remaining should be a product of 2 primes
        for j in range(2, remaining + 1):
            if not is_prime(j):
                continue
            if remaining % j != 0:
                continue
            k = remaining // j
            if is_prime(k):
                return True
    return False
